"use client";

import { Code2, Palette, Rocket, Zap, BarChart, Settings } from "lucide-react";
import Link from "next/link";
import { ArrowRight } from "lucide-react";

const services = [
  {
    id: "web-development",
    title: "Web Development",
    description: "Custom, scalable web applications built with modern technologies like Next.js and TypeScript.",
    icon: Code2,
    color: "from-blue-500 to-cyan-500",
  },
  {
    id: "ui-ux",
    title: "UI/UX Design",
    description: "Beautiful, conversion-focused interfaces designed with a focus on user psychology and brand identity.",
    icon: Palette,
    color: "from-purple-500 to-pink-500",
  },
  {
    id: "saas-mvp",
    title: "SaaS MVP Development",
    description: "Launch your SaaS idea fast with a production-ready MVP built for speed and long-term scalability.",
    icon: Rocket,
    color: "from-orange-500 to-red-500",
  },
  {
    id: "performance",
    title: "Performance Optimization",
    description: "Audit and optimize your existing applications to reach perfect Lighthouse scores and better Core Web Vitals.",
    icon: Zap,
    color: "from-yellow-500 to-orange-500",
  },
  {
    id: "api-integration",
    title: "API & System Integration",
    description: "Seamlessly connect your business systems with external APIs, payment gateways, and CRM platforms.",
    icon: Settings,
    color: "from-green-500 to-emerald-500",
  },
  {
    id: "growth",
    title: "Growth Engineering",
    description: "Data-driven development strategies aimed at increasing your conversion rates and digital footprint.",
    icon: BarChart,
    color: "from-blue-400 to-indigo-500",
  },
];

export default function ServicesOverview() {
  return (
    <section className="section-padding px-8 md:px-16 relative bg-background">
      <div className="max-w-7xl mx-auto">
        <div className="flex flex-col md:flex-row justify-between items-end mb-20 gap-8">
          <div className="max-w-2xl">
            <h2 className="text-4xl md:text-5xl lg:text-7xl font-black text-white mb-10 font-outfit tracking-tight leading-[1.1]">
              Comprehensive <br />
              <span className="text-gradient">Digital Services.</span>
            </h2>
            <p className="text-foreground/60 text-lg md:text-2xl leading-relaxed max-w-3xl">
              We provide a full spectrum of engineering services geared towards 
              performance and conversion. Every line of code is written with 
              your business goals in mind.
            </p>
          </div>
          <Link 
            href="/services" 
            className="flex items-center gap-2 text-primary font-semibold hover:gap-4 transition-all pb-2"
          >
            Explore All Services <ArrowRight className="w-5 h-5" />
          </Link>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 lg:gap-12">
          {services.map((service, index) => (
            <div 
              key={service.id}
              className="group glass p-10 md:p-12 rounded-[2.5rem] hover:border-primary/50 transition-all duration-500 relative overflow-hidden"
            >
              {/* Card Glow */}
              <div className={cn(
                "absolute -top-12 -right-12 w-32 h-32 bg-gradient-to-br blur-3xl opacity-0 group-hover:opacity-20 transition-opacity duration-500",
                service.color
              )} />
              
              <div className={cn(
                "w-14 h-14 bg-gradient-to-br rounded-2xl flex items-center justify-center mb-8 shadow-lg transition-transform group-hover:scale-110 group-hover:rotate-3 duration-500",
                service.color
              )}>
                <service.icon className="w-7 h-7 text-white" />
              </div>

              <h3 className="text-2xl font-bold text-white mb-5 font-outfit tracking-tight">
                {service.title}
              </h3>
              <p className="text-foreground/60 text-base leading-relaxed mb-10">
                {service.description}
              </p>

              <Link 
                href={`/services#${service.id}`}
                className="text-white font-semibold text-sm flex items-center gap-2 group-hover:text-primary transition-colors"
              >
                Learn More <ArrowRight className="w-4 h-4" />
              </Link>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

function cn(...inputs: any[]) {
  return inputs.filter(Boolean).join(" ");
}
