"use client";

import { motion } from "framer-motion";
import Link from "next/link";
import { ArrowRight, Globe, Zap, Cpu, Code2, Database, Layout, ShieldCheck } from "lucide-react";
import { cn } from "@/lib/utils";

const techIcons = [
  { icon: Globe, label: "Next.js", color: "text-white" },
  { icon: Zap, label: "Framer", color: "text-amber-400" },
  { icon: Cpu, label: "React", color: "text-cyan-400" },
  { icon: Code2, label: "TypeScript", color: "text-blue-500" },
  { icon: Database, label: "Supabase", color: "text-emerald-500" },
  { icon: Layout, label: "Tailwind", color: "text-sky-400" },
  { icon: ShieldCheck, label: "Auth.js", color: "text-purple-500" },
];

export default function Hero() {
  return (
    <section className="relative min-h-screen bg-[#030303] flex flex-col items-center pt-52 pb-24 px-8 overflow-hidden">
      {/* Background radial glow */}
      <div className="absolute top-0 left-0 w-full h-full -z-10 bg-[radial-gradient(circle_at_50%_0%,#1a1a1a,transparent_70%)] opacity-80" />

      {/* Top Banner */}
      <motion.div 
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        className="mb-12 px-6 py-2 bg-primary/10 border border-primary/20 rounded-full text-sm font-medium text-primary shadow-lg shadow-primary/5"
      >
        Ranked #1 Web Development Agency for 2024. <Link href="/blogs" className="underline ml-2">See awards</Link>
      </motion.div>

      <div className="max-w-6xl mx-auto text-center z-10 mb-20">
        <motion.h1 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="text-6xl md:text-8xl lg:text-[7.5rem] font-bold text-white leading-[1] mb-12 tracking-[-0.04em] font-outfit"
        >
          Engineering <span className="text-primary italic">high-performance</span> digital <br className="hidden md:block" />
          products and scalable web.
        </motion.h1>

        <motion.p 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.2 }}
          className="text-xl md:text-2xl text-white/50 max-w-4xl mx-auto mb-16 leading-relaxed font-medium"
        >
          Webkaro is a community-driven collective helping startups and enterprises <br className="hidden md:block" />
          build their next-gen SaaS, e-commerce, and complex web applications.
        </motion.p>

        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 0.4 }}
          className="flex flex-col sm:flex-row items-center justify-center gap-8"
        >
          <Link 
            href="/contact"
            className="group relative w-full sm:w-auto px-14 py-5 bg-white text-black rounded-2xl font-black transition-all hover:scale-105 active:scale-95 overflow-hidden text-xl shadow-[0_0_50px_rgba(255,255,255,0.1)]"
          >
            <span className="relative z-10">Start Your Project</span>
            <div className="absolute inset-0 bg-gradient-to-r from-primary/10 via-transparent to-primary/10 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
          </Link>

          <Link 
            href="/contact"
            className="group relative w-full sm:w-auto px-14 py-5 bg-black/40 backdrop-blur-md text-white border border-white/10 rounded-2xl font-black transition-all hover:bg-white/5 hover:border-white/20 active:scale-95 text-xl"
          >
            <span className="relative z-10">Book a Consultation</span>
            <div className="absolute inset-0 bg-gradient-to-tr from-primary/5 via-transparent to-purple-500/5 opacity-0 group-hover:opacity-100 transition-all duration-700" />
            
            {/* Corner Gloom */}
            <div className="absolute -top-10 -right-10 w-20 h-20 bg-primary/10 blur-[40px] opacity-0 group-hover:opacity-100 transition-opacity duration-700" />
            <div className="absolute -bottom-10 -left-10 w-20 h-20 bg-purple-500/10 blur-[40px] opacity-0 group-hover:opacity-100 transition-opacity duration-700" />
          </Link>
        </motion.div>
      </div>

      {/* Circular Tech Spotlight */}
      <div className="relative w-full max-w-5xl mt-24 mb-32 flex justify-center items-center h-[500px]">
        {/* Orbits */}
        <div className="absolute inset-0 flex justify-center items-center pointer-events-none">
          {[1, 2, 3].map((i) => (
            <div 
              key={i}
              className="absolute border border-white/5 rounded-full"
              style={{ 
                width: `${i * 300}px`, 
                height: `${i * 300}px`,
                opacity: 0.7 / i
              }}
            />
          ))}
        </div>

        {/* Central Logo */}
        <div className="relative z-20 w-32 h-32 bg-primary flex items-center justify-center rounded-[2.5rem] shadow-2xl shadow-primary/40 ring-8 ring-primary/5">
           <span className="text-5xl font-black text-white italic">WK</span>
        </div>

        {/* Tech Icons (Orbiting) */}
        {techIcons.map((tech, idx) => {
          const angle = (idx / techIcons.length) * Math.PI * 2;
          return (
            <motion.div
              key={tech.label}
              initial={{ scale: 0, opacity: 0 }}
              animate={{ 
                scale: 1, 
                opacity: 1,
              }}
              transition={{ 
                duration: 1, 
                delay: 0.5 + (idx * 0.1),
                type: "spring",
                stiffness: 100
              }}
              style={{
                // Responsive radius logic using CSS variables
                left: "50%",
                top: "50%",
                x: `calc(-50% + ${Math.cos(angle)} * var(--radius, 100px))`,
                y: `calc(-50% + ${Math.sin(angle)} * var(--radius, 100px))`,
              } as any}
              className={cn(
                "absolute z-10 p-3 md:p-5 bg-[#0a0a0a] border border-white/10 rounded-2xl md:rounded-[1.75rem] shadow-2xl flex flex-col items-center gap-2 md:gap-3 transition-colors duration-500",
                "[--radius:120px] md:[--radius:220px]"
              )}
              whileHover={{ scale: 1.1, borderColor: "rgba(255,255,255,0.3)", backgroundColor: "#111" }}
            >
              <tech.icon className={cn("w-6 h-6 md:w-10 md:h-10", tech.color)} />
              <span className="text-[8px] md:text-[10px] font-bold uppercase tracking-widest text-white/40">{tech.label}</span>
            </motion.div>
          );
        })}
      </div>

      {/* Payment Logos Footer */}
      <div className="w-full max-w-7xl mx-auto flex flex-col items-center gap-12 pt-20 border-t border-white/5">
        <p className="text-white/30 text-xs font-bold uppercase tracking-[0.3em]">
          Acceptable payment methods worldwide
        </p>
        <div className="flex flex-wrap justify-center items-center gap-16 opacity-40 grayscale hover:grayscale-0 transition-all duration-700">
           <div className="flex items-center gap-4 hover:scale-110 transition-transform cursor-pointer">
              <img src="https://upload.wikimedia.org/wikipedia/commons/b/b5/PayPal.svg" alt="PayPal" className="h-10 w-auto invert" />
              <span className="text-2xl font-bold text-white tracking-widest italic pt-1">PAYPAL</span>
           </div>
           <div className="flex items-center gap-4 hover:scale-110 transition-transform cursor-pointer">
              <img src="https://upload.wikimedia.org/wikipedia/commons/5/5e/Visa_Inc._logo.svg" alt="Visa" className="h-8 w-auto invert" />
              <span className="text-2xl font-bold text-white tracking-widest pt-1">VISA</span>
           </div>
           <div className="flex items-center gap-4 hover:scale-110 transition-transform cursor-pointer">
              <img src="https://upload.wikimedia.org/wikipedia/commons/2/2a/Mastercard-logo.svg" alt="Mastercard" className="h-12 w-auto" />
              <span className="text-2xl font-bold text-white tracking-widest pt-1 uppercase">Mastercard</span>
           </div>
           <div className="flex items-center gap-4 hover:scale-110 transition-transform cursor-pointer">
              <ShieldCheck className="w-10 h-10 text-white" />
              <span className="text-2xl font-bold text-white tracking-widest pt-1 uppercase">Secure Pay</span>
           </div>
        </div>
      </div>
    </section>
  );
}
