"use client";

import { Users, ShieldCheck, Zap, Globe } from "lucide-react";
import { cn } from "@/lib/utils";

const features = [
  {
    icon: Users,
    title: "Collaborative Collective",
    description: "Our community of vetted developers and designers work together to bring diverse perspectives to every project.",
  },
  {
    icon: ShieldCheck,
    title: "Vetted Expertise",
    description: "Every member of our collective undergoes a rigorous vetting process to ensure top-tier development standards.",
  },
  {
    icon: Zap,
    title: "High Performance",
    description: "We don't just build websites; we engineer high-performance digital machines designed for speed and scale.",
  },
  {
    icon: Globe,
    title: "Global Standards",
    description: "Following modern architecture patterns and global best practices for scalable, maintainable products.",
  },
];

export default function ExpertCommunity() {
  return (
    <section className="section-padding px-8 md:px-16 relative overflow-hidden bg-background">
      <div className="max-w-7xl mx-auto">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-24 lg:gap-32 items-center">
          <div>
            <h2 className="text-4xl md:text-5xl lg:text-7xl font-black text-white mb-10 font-outfit tracking-tight leading-[1.1]">
              Powered by an Expert <br />
              <span className="text-gradient">Collective.</span>
            </h2>
            <p className="text-foreground/70 text-lg md:text-2xl mb-16 leading-relaxed max-w-2xl">
              Webkaro is more than just a development agency. We are a community-driven 
              collective of high-performance developers, designers, and strategists 
              collaborating to deliver exceptional digital products.
            </p>
            
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
              {features.map((feature, index) => (
                <div key={index} className="space-y-3">
                  <div className="w-12 h-12 bg-primary/10 rounded-xl flex items-center justify-center">
                    <feature.icon className="w-6 h-6 text-primary" />
                  </div>
                  <h4 className="text-white font-semibold">{feature.title}</h4>
                  <p className="text-foreground/60 text-sm leading-relaxed">
                    {feature.description}
                  </p>
                </div>
              ))}
            </div>
          </div>

          <div className="relative">
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[120%] h-[120%] bg-primary/5 blur-[100px] rounded-full" />
            <div className="grid grid-cols-2 gap-4 relative">
              <div className="space-y-4">
                <div className="glass p-8 rounded-3xl h-48 flex flex-col justify-end animate-float">
                  <p className="text-3xl font-bold text-white">50+</p>
                  <p className="text-sm text-foreground/50">Experts</p>
                </div>
                <div className="glass p-8 rounded-3xl h-64 flex flex-col justify-end">
                  <p className="text-3xl font-bold text-white">100%</p>
                  <p className="text-sm text-foreground/50">Collective Growth</p>
                </div>
              </div>
              <div className="space-y-4 pt-8">
                <div className="glass p-8 rounded-3xl h-64 flex flex-col justify-end">
                  <p className="text-3xl font-bold text-white">Global</p>
                  <p className="text-sm text-foreground/50">Reach</p>
                </div>
                <div className="glass p-8 rounded-3xl h-48 flex flex-col justify-end animate-float" style={{ animationDelay: "1s" }}>
                  <p className="text-3xl font-bold text-white">24/7</p>
                  <p className="text-sm text-foreground/50">Collaboration</p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
